using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;
public static class AuthorHud07{public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var setup=EditorSceneManager.GetSceneManagerSetup();try{foreach(var name in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+name+".unity");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var scaler=h.GetComponent<UnityEngine.UI.CanvasScaler>();scaler.referenceResolution=new Vector2(1280,720);scaler.matchWidthOrHeight=1;EditorUtility.SetDirty(scaler);var power=h.GetComponentsInChildren<RectTransform>(true).Single(r=>r.name=="PowerSummary");power.SetParent(h.Groups.ConstructionSlides.Single(s=>s.Direction==Vector2.left).Host,false);power.anchorMin=power.anchorMax=power.pivot=new Vector2(0,1);power.anchoredPosition=new Vector2(16,-16);power.sizeDelta=new Vector2(280,60);h.Layout.TestShortcuts=h.GetComponentsInChildren<RectTransform>(true).Single(r=>r.name=="TestShortcuts");h.Layout.TestButtons=new[]{"infinite-resources","quick-day","quick-night"}.Select(id=>(RectTransform)h.Buttons.Single(b=>b.Id==id).View.transform).ToArray();h.Layout.FloatingSizes=new[]{new Vector2(580,420),new Vector2(470,260)};EditorUtility.SetDirty(h.Layout);foreach(var popup in h.Layout.FloatingPanels){foreach(var scroll in popup.GetComponentsInChildren<UnityEngine.UI.ScrollRect>(true)){var r=(RectTransform)scroll.transform;r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=new Vector2(8,10);r.offsetMax=new Vector2(-8,-46);EditorUtility.SetDirty(r);}}var service=h.Sandbox.RailwayHud.GetComponent<RailwayOverview>().Services;foreach(var summary in new[]{service.CargoSummary,service.DefenseSummary}){summary.textWrappingMode=TMPro.TextWrappingModes.Normal;summary.overflowMode=TMPro.TextOverflowModes.Overflow;EditorUtility.SetDirty(summary);}var objective=h.Layout.FirstLoopObjective;if(objective!=null){var label=objective.GetComponentInChildren<TMPro.TMP_Text>(true);label.rectTransform.anchorMin=Vector2.zero;label.rectTransform.anchorMax=Vector2.one;label.rectTransform.offsetMin=new Vector2(12,8);label.rectTransform.offsetMax=new Vector2(-12,-8);label.alignment=TMPro.TextAlignmentOptions.TopLeft;label.textWrappingMode=TMPro.TextWrappingModes.Normal;EditorUtility.SetDirty(label);}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}return "Reference resolution 1280x720; power summary belongs to construction at top left";}}
